(window.DETAIL_C = window.DETAIL_C || {})["phy-12-08"] = {"phy-12-08-m01":{"idea":"Coulomb's law: the force between two point charges falls with the square of the distance.","steps":["The force grows with the product q₁q₂.","It falls as 1/r².","So F = k q₁q₂/r², along the line joining the charges."],"others":"Dividing by r (not r²) gives the wrong power. Multiplying by r² makes the force grow with distance. A sum q₁ + q₂ ignores that both charges are needed.","trap":"Inverse square, product of charges.","answer":"kq₁q₂/r²"},"phy-12-08-m02":{"idea":"Electric field is force per unit charge, so its units are N/C, which equal V/m.","steps":["E = F/q gives N/C.","Also E = V/d, so the unit is V/m.","N/C and V/m are the same unit."],"others":"V m has the wrong dimensions. J/C is volt, the unit of potential. N C is a product, not a ratio.","trap":"Field: V/m. Potential: V (or J/C).","answer":"volt per metre (V/m)"},"phy-12-08-m03":{"idea":"Doubling the distance cuts an inverse-square force to a quarter.","steps":["F ∝ 1/r².","r becomes 2r, so r² becomes 4r².","F becomes F/4."],"others":"Four times larger goes the wrong way. One half would be 1/r. Twice as large is the wrong direction.","trap":"Square the factor.","answer":"one quarter"},"phy-12-08-m04":{"idea":"Force is proportional to the product of the charges.","steps":["F ∝ q₁ q₂.","Both charges are doubled: 2 × 2 = 4.","So the force is four times larger."],"others":"Twice would be right if only one charge doubled. Eight times is not a product of the factors. The same ignores the change.","trap":"Both charges change, so multiply the factors.","answer":"four times as large"},"phy-12-08-m05":{"idea":"Field lines of static charges have clear rules.","steps":["Lines start on positive charges and end on negative charges.","They never cross, because the field has one direction at a point.","They are not closed loops in electrostatics."],"others":"Closed loops belong to magnetic fields. Lines cannot cross. Starting on negative charges is reversed.","trap":"Out from +, into −.","answer":"begin on positive charges, end on negative charges and never cross"},"phy-12-08-m06":{"idea":"Inside a conductor in equilibrium the field is zero.","steps":["Free charges would move if there were a field inside.","They keep moving until they cancel the field.","So the field inside is zero."],"others":"A non-zero uniform field would keep charges moving. A field towards the surface or equal to the outside field is not possible inside.","trap":"Zero inside, perpendicular to the surface just outside.","answer":"zero"},"phy-12-08-m07":{"idea":"Gauss's law links flux with the charge enclosed.","steps":["Flux through a closed surface = q_enclosed/ε₀.","Only the enclosed charge counts.","The shape of the surface does not matter."],"others":"The form with 4πε₀r² is a field, not a flux. Zero is only for no enclosed charge. Multiplying by ε₀ has the wrong units.","trap":"Divide by ε₀.","answer":"q_enclosed/ε₀"},"phy-12-08-m08":{"idea":"A large charged sheet makes a uniform field on each side.","steps":["Use a pillbox Gaussian surface through the sheet.","Flux goes out through both faces: 2EA = σA/ε₀.","So E = σ/(2ε₀), the same at every distance."],"others":"σ/ε₀ is the field near a conductor surface. Dependence on distance would apply to a point charge.","trap":"Sheet: σ/(2ε₀), independent of distance.","answer":"σ/(2ε₀), independent of the distance from the sheet"},"phy-12-08-m09":{"idea":"A charged thin shell has no field inside, and outside it acts like a point charge.","steps":["Inside, a Gaussian sphere encloses no charge, so E = 0.","Outside, the shell acts like a point charge Q at its centre.","So E = kQ/r² for r > R."],"others":"The other options give a field inside or use R instead of r outside.","trap":"Inside: zero. Outside: kQ/r².","answer":"zero inside, and kQ/r² outside"},"phy-12-08-m10":{"idea":"The potential of a point charge falls as 1/r.","steps":["Potential is the work per unit charge to bring a test charge from infinity.","For a point charge: V = kq/r.","It is a scalar."],"others":"kq/(2r) has a stray factor. kqr rises with distance. kq/r² is the field, not the potential.","trap":"Potential 1/r, field 1/r².","answer":"kq/r"},"phy-12-08-m11":{"idea":"Potential is energy per unit charge, so it is a scalar.","steps":["V = W/q has units joule per coulomb, which is the volt.","It has only size, no direction.","So potential is a scalar in J/C."],"others":"N/C is the unit of the field. A vector would need a direction.","trap":"Field: vector, N/C. Potential: scalar, J/C.","answer":"a scalar, with the unit joule per coulomb"},"phy-12-08-m12":{"idea":"Dipole moment is charge times separation, from negative to positive.","steps":["The separation is 2a.","Size p = q × 2a = 2aq.","Direction: from −q to +q."],"others":"Direction from +q to −q is reversed. 2aq/r² has the wrong dimensions. aq uses half the separation.","trap":"Negative to positive.","answer":"2aq, directed from −q to +q"},"phy-12-08-m13":{"idea":"A dipole in a uniform field feels a torque of size pE sin θ.","steps":["τ = p × E.","Its magnitude is pE sin θ.","It turns the dipole towards the field."],"others":"pE alone is the maximum value at 90°. pE cos θ would give zero torque at 90°. p sin θ/E has wrong units.","trap":"Zero torque at θ = 0° and 180°.","answer":"pE sinθ"},"phy-12-08-m14":{"idea":"Stable equilibrium is where the potential energy is lowest.","steps":["U = −pE cos θ.","At θ = 0° the energy is −pE, the minimum.","A small turn from there is pulled back, so it is stable."],"others":"At 180° U is the maximum, so it is unstable. 90° and 45° are not equilibrium positions for a free dipole.","trap":"Stable: along the field.","answer":"θ = 0°, the dipole along the field"},"phy-12-08-m15":{"idea":"In a uniform field the forces on the two charges cancel.","steps":["+q feels qE one way, −q feels qE the other way.","The two forces are equal and opposite.","So the net force is zero, though a torque remains."],"others":"qE, 2pE and pE do not describe a net force; pE is the torque scale.","trap":"Zero force does not mean zero torque.","answer":"zero"},"phy-12-08-m16":{"idea":"Electrostatic force is conservative, so work depends only on the end points.","steps":["W = qV, where V is the potential difference.","The path does not matter.","Speed and mass of the charge do not matter either."],"others":"The speed, mass and path length do not enter W = qV.","trap":"Work = charge × potential difference.","answer":"only q and V, and not on the path taken"},"phy-12-08-m17":{"idea":"Along an equipotential surface the potential does not change.","steps":["ΔV = 0 along the surface, so the work is zero for any move along it.","That needs the force to have no component along the surface.","So the field is perpendicular to the surface."],"others":"Work is zero in every direction along the surface, not only against the field. The field is not zero there. A tangent field would do work.","trap":"Field lines cross equipotentials at right angles.","answer":"no work is done in moving a charge, and the field is perpendicular to the surface"},"phy-12-08-m18":{"idea":"Capacitance rises with plate area and falls with plate gap.","steps":["More area stores more charge for the same voltage.","A bigger gap reduces the capacitance.","So C = ε₀A/d."],"others":"ε₀Ad grows with the gap. ε₀d/A has them upside down. A/(ε₀d) has the wrong constant placement.","trap":"Area on top, distance below.","answer":"ε₀A/d"},"phy-12-08-m19":{"idea":"Capacitance is inversely proportional to the plate separation.","steps":["C = ε₀A/d.","d becomes 2d.","So C becomes half."],"others":"Four times and double would need d to shrink. Unchanged ignores d.","trap":"Pull the plates apart: C falls.","answer":"half"},"phy-12-08-m20":{"idea":"A disconnected capacitor keeps its charge, so inserting a dielectric lowers the voltage.","steps":["The battery is off, so Q stays the same.","The dielectric raises the capacitance to KC.","V = Q/C then falls by the factor K."],"others":"If the charge changed, that would need a battery. A fall in capacitance is wrong for a dielectric. A rising voltage is wrong because C rises.","trap":"Battery off: charge fixed. Battery on: voltage fixed.","answer":"the charge stays, the capacitance rises K times and the potential difference falls K times"},"phy-12-08-m21":{"idea":"In series the reciprocals of the capacitances add.","steps":["Each capacitor carries the same charge Q.","The voltages add: Q/C = Q/C₁ + Q/C₂.","So 1/C = 1/C₁ + 1/C₂."],"others":"C₁ + C₂ is the parallel rule. The other two forms mix the rules.","trap":"Capacitors are the opposite of resistors here.","answer":"1/C = 1/C₁ + 1/C₂"},"phy-12-08-m22":{"idea":"A capacitor stores energy as the charge is built up from zero voltage.","steps":["The voltage rises from 0 to V as the charge is added.","The average voltage is V/2.","So U = ½ Q V = ½ C V²."],"others":"½CV and CV are not energies (wrong units). CV² has no half.","trap":"Remember the half and the square.","answer":"½CV²"},"phy-12-08-m23":{"idea":"For two capacitors in series use 1/C = 1/C₁ + 1/C₂.","steps":["1/C = 1/6 + 1/3 = 1/6 + 2/6 = 3/6 = 1/2.","C = 2 μF.","The result is smaller than the smallest capacitor."],"others":"9 μF is the parallel sum. 4.5 μF is the average. 18 μF is the product.","trap":"Series always gives less than the smallest.","answer":"2 μF"},"phy-12-08-m24":{"idea":"Two equal like charges cancel each other's field at the midpoint.","steps":["Each charge makes a field of equal size at the midpoint.","The two fields point in opposite directions.","So they cancel and the net field is zero."],"others":"Not along the line towards one charge, since neither wins. Not equal to or double that of one charge.","trap":"The potential at the midpoint is not zero, only the field.","answer":"zero"},"phy-12-08-m25":{"idea":"Charge comes in whole units of e. That is quantisation.","steps":["Any charge is Q = n e, with n an integer.","So charge is not continuous.","This property is called quantisation of charge."],"others":"Conservation says the net charge of an isolated system stays fixed. Continuity and additivity do not describe whole units.","trap":"Quantised = comes in packets. Conserved = total fixed.","answer":"quantisation of charge"},"phy-12-08-m26":{"idea":"Rubbing moves electrons, never protons.","steps":["Glass rubbed with silk gives electrons to the silk.","Glass is left short of electrons, so it is positive.","The silk gains them and becomes negative."],"others":"Protons are fixed in nuclei. Gaining electrons would make the glass negative.","trap":"Positive means electrons lost.","answer":"it loses electrons to the silk"},"phy-12-08-m27":{"idea":"Surface charge density is charge per unit area.","steps":["σ = Q/A.","Unit: coulomb divided by square metre.","So it is C/m²."],"others":"C/m is linear density. C/m³ is volume density. C m is a dipole moment.","trap":"Line: C/m. Surface: C/m². Volume: C/m³.","answer":"coulomb per square metre (C/m²)"},"phy-12-08-m28":{"idea":"The dielectric constant compares capacitance with and without the material.","steps":["K = C/C₀, with C the capacitance with the dielectric and C₀ in vacuum.","K is always at least 1.","The polarised material reduces the field, so the same charge needs less voltage."],"others":"Area over separation is geometry. Capacitance times voltage is charge. A ratio of charges is not K.","trap":"K = C/C₀.","answer":"the ratio of the capacitance with the material between the plates to that with vacuum"},"phy-12-08-n01":{"idea":"Use Coulomb's law F = k q₁q₂/r².","steps":["q₁q₂ = 2 × 10⁻⁶ × 3 × 10⁻⁶ = 6 × 10⁻¹².","F = 9 × 10⁹ × 6 × 10⁻¹²/(0.3)² = 0.054/0.09.","F = 0.6 N, repulsive."],"trap":"Convert μC to C.","answer":"0.6 N"},"phy-12-08-n02":{"idea":"Field of a point charge: E = kq/r².","steps":["q = 4 × 10⁻⁶ C and r = 0.2 m.","E = 9 × 10⁹ × 4 × 10⁻⁶/0.04.","E = 36 × 10³/0.04 = 9 × 10⁵ N/C."],"trap":"The answer is in units of 10⁵ N/C: 9.0.","answer":"9.0 (in units of 10⁵ N/C)"},"phy-12-08-n03":{"idea":"Potential of a point charge: V = kq/r.","steps":["q = 5 × 10⁻⁹ C and r = 0.1 m.","V = 9 × 10⁹ × 5 × 10⁻⁹/0.1.","V = 45/0.1 = 450 V."],"trap":"Potential is a scalar, so no direction needed.","answer":"450 V"},"phy-12-08-n04":{"idea":"Work equals charge times potential difference.","steps":["W = q V.","= 2 × 10⁻⁶ × 100.","= 2 × 10⁻⁴ J = 200 μJ."],"trap":"1 μJ = 10⁻⁶ J.","answer":"200 μJ"},"phy-12-08-n05":{"idea":"Torque on a dipole: τ = pE sin θ.","steps":["p = 3.0 × 10⁻⁸ C m, E = 5.0 × 10⁴ N/C, sin 30° = 0.5.","τ = 3.0 × 10⁻⁸ × 5.0 × 10⁴ × 0.5.","τ = 7.5 × 10⁻⁴ N m."],"trap":"Use sin of the angle between p and E.","answer":"7.5 (in units of 10⁻⁴ N m)"},"phy-12-08-n06":{"idea":"Capacitance of parallel plates: C = ε₀A/d.","steps":["ε₀ = 8.85 × 10⁻¹² F/m, A = 0.02 m², d = 0.001 m.","C = 8.85 × 10⁻¹² × 0.02/0.001.","C = 1.77 × 10⁻¹⁰ F = 177 pF."],"trap":"Convert mm to metres.","answer":"177 pF"},"phy-12-08-n07":{"idea":"Series capacitors: 1/C = 1/C₁ + 1/C₂.","steps":["1/C = 1/6 + 1/3 = 1/2.","C = 2.0 μF.","Also C = (6 × 3)/(6 + 3) = 2 μF."],"trap":"Series is always smaller than the smallest capacitor.","answer":"2.0 μF"},"phy-12-08-n08":{"idea":"Energy stored is U = ½CV².","steps":["C = 10 × 10⁻⁶ F and V = 200 V.","V² = 40 000.","U = ½ × 10 × 10⁻⁶ × 40 000 = 0.20 J."],"trap":"Square the voltage, then halve.","answer":"0.20 J"},"phy-12-08-n09":{"idea":"Charge on a capacitor is Q = CV.","steps":["C = 5 μF and V = 12 V.","Q = 5 × 12.","Q = 60 μC."],"trap":"Units: μF × V = μC.","answer":"60 μC"},"phy-12-08-n10":{"idea":"Gauss's law: flux = q/ε₀.","steps":["q = 8.85 × 10⁻⁹ C and ε₀ = 8.85 × 10⁻¹² F/m.","Φ = 8.85 × 10⁻⁹/8.85 × 10⁻¹².","Φ = 1000 N m²/C."],"trap":"The size and shape of the surface do not matter.","answer":"1000 N m²/C"}};
